<?php require 'config/functions.php';$items=cart_products($pdo);if(!$items)redirect('cart.php');$pageTitle='Checkout';$errors=[];$values=['customer_name'=>'','email'=>'','phone'=>'','address'=>''];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach($values as $k=>$v)$values[$k]=trim($_POST[$k]??'');if(strlen($values['customer_name'])<2||strlen($values['customer_name'])>120)$errors[]='Nama tidak valid.';if(!filter_var($values['email'],FILTER_VALIDATE_EMAIL)||strlen($values['email'])>150)$errors[]='Email tidak valid.';if(!preg_match('/^[0-9+() -]{8,30}$/',$values['phone']))$errors[]='Nomor telepon tidak valid.';if(strlen($values['address'])<10)$errors[]='Alamat minimal 10 karakter.';if(!$errors){try{$pdo->beginTransaction();$fresh=[];$total=0;$lock=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');foreach($_SESSION['cart'] as $id=>$qty){$lock->execute([(int)$id]);$product=$lock->fetch();if(!$product||$qty<1||$product['stock']<$qty)throw new RuntimeException('Stok produk berubah. Periksa keranjang kembali.');$product['quantity']=$qty;$fresh[]=$product;$total+=$qty*$product['price'];}$order=$pdo->prepare('INSERT INTO orders(customer_name,email,phone,address,total) VALUES(?,?,?,?,?)');$order->execute([$values['customer_name'],$values['email'],$values['phone'],$values['address'],$total]);$orderId=$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');$update=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($fresh as $item){$insert->execute([$orderId,$item['id'],$item['name'],$item['price'],$item['quantity']]);$update->execute([$item['quantity'],$item['id']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['completed_order']=(int)$orderId;redirect('success.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Pesanan gagal diproses. Coba lagi.';}}}$total=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));include 'partials/header.php';?><section class="container section"><h1 class="page-title">Checkout</h1><div class="cart-layout"><form method="post" class="checkout-form"><h2>Informasi Pengiriman</h2><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nama lengkap<input name="customer_name" maxlength="120" value="<?=e($values['customer_name'])?>" required></label><label>Email<input type="email" name="email" maxlength="150" value="<?=e($values['email'])?>" required></label><label>Nomor telepon<input name="phone" maxlength="30" value="<?=e($values['phone'])?>" required></label><label>Alamat lengkap<textarea name="address" rows="5" required><?=e($values['address'])?></textarea></label><button class="btn btn-dark full">Buat Pesanan</button><p class="muted">Demo: pesanan dicatat di database, belum terhubung pembayaran dan pengiriman otomatis.</p></form><aside class="summary"><h2>Pesananmu</h2><?php foreach($items as $item):?><div class="summary-row"><span><?=e($item['name'])?> × <?=(int)$item['quantity']?></span><strong><?=rupiah($item['price']*$item['quantity'])?></strong></div><?php endforeach;?><hr><div class="summary-row"><strong>Total</strong><strong><?=rupiah($total)?></strong></div></aside></div></section><?php include 'partials/footer.php';?>